<template><div class="page"><section class="welcome"><div><h1>欢迎回来，教师！</h1><p>上传教学资料，构建本地知识库，智能生成题目并快速创建试卷。</p></div><div class="date"><Calendar/> {{dateText}}</div></section><PageState :loading="loading" :error="error" @retry="load"><div class="metric-grid"><div v-for="item in metrics" :key="item.key" class="metric-card card" @click="router.push(item.path)" role="link" tabindex="0" @keydown.enter="router.push(item.path)"><div class="metric-icon" :style="{background:item.bg,color:item.color}"><component :is="item.icon"/></div><div><div class="metric-label">{{item.label}}</div><div class="metric-value tabular">{{Number(stats[item.key]||0).toLocaleString()}}</div></div></div></div></PageState><div class="quick-actions card"><span>快速操作</span><el-button v-for="action in actions" :key="action.path" @click="router.push(action.path)"><component :is="action.icon"/>{{action.label}}</el-button></div><div class="dashboard-grid"><RecentTable title="最近上传文件" more="/knowledge/files"><el-table :data="files" height="250"><el-table-column prop="original_name" label="文件名" show-overflow-tooltip/><el-table-column prop="course_name" label="所属课程" width="120"/><el-table-column label="状态" width="90"><template #default="scope"><StatusTag :value="scope.row.parse_status"/></template></el-table-column><el-table-column label="上传时间" width="150"><template #default="scope">{{formatTime(scope.row.created_at)}}</template></el-table-column></el-table></RecentTable><RecentTable title="最近生成题目" more="/questions"><el-table :data="questions" height="250"><el-table-column prop="stem" label="题目" show-overflow-tooltip/><el-table-column prop="question_type" label="题型" width="105"/><el-table-column prop="difficulty" label="难度" width="70"/><el-table-column label="审核" width="90"><template #default="scope"><StatusTag :value="scope.row.review_status"/></template></el-table-column></el-table></RecentTable><RecentTable title="最近创建试卷" more="/papers"><el-table :data="papers" height="250"><el-table-column prop="name" label="试卷名称" show-overflow-tooltip/><el-table-column prop="course_name" label="课程" width="110"/><el-table-column prop="question_count" label="题数" width="60"/><el-table-column label="创建时间" width="150"><template #default="scope">{{formatTime(scope.row.created_at)}}</template></el-table-column></el-table></RecentTable></div><div class="chart-grid three"><div class="card"><div class="card-header"><span class="card-title">题型分布</span></div><div ref="typeEl" class="chart" aria-label="题型分布图"></div></div><div class="card"><div class="card-header"><span class="card-title">难度分布</span></div><div ref="difficultyEl" class="chart" aria-label="难度分布图"></div></div><div class="card"><div class="card-header"><span class="card-title">文件解析状态</span></div><div ref="parseEl" class="chart" aria-label="文件解析状态图"></div></div></div></div></template>
<script setup>
import{ref,computed,onMounted,onUnmounted,nextTick}from'vue';import{useRouter}from'vue-router';import*as echarts from'echarts';import{dashboardApi}from'../../api';import PageState from'../../components/PageState.vue';import StatusTag from'../../components/StatusTag.vue';import RecentTable from'./RecentTable.vue'
const router=useRouter(),loading=ref(true),error=ref(''),stats=ref({}),files=ref([]),questions=ref([]),papers=ref([]),typeEl=ref(),difficultyEl=ref(),parseEl=ref();let charts=[]
const metrics=[{key:'courses',label:'课程总数',icon:'Reading',path:'/courses',bg:'#eaf3ff',color:'#1677ff'},{key:'files',label:'知识库文件',icon:'Document',path:'/knowledge/files',bg:'#e8fbff',color:'#10b6cf'},{key:'knowledge_points',label:'知识点数量',icon:'Key',path:'/knowledge-points',bg:'#e9faf5',color:'#16a874'},{key:'questions',label:'题库题目',icon:'Tickets',path:'/questions',bg:'#f0efff',color:'#6f67e8'},{key:'pending_questions',label:'待审核题目',icon:'Clock',path:'/questions?review_status=PENDING',bg:'#fff4e9',color:'#ee8b2e'},{key:'papers',label:'已创建试卷',icon:'Memo',path:'/papers',bg:'#edf5ff',color:'#3988e8'}]
const actions=[{label:'上传知识库',path:'/knowledge/upload',icon:'UploadFilled'},{label:'AI智能出题',path:'/generation/create',icon:'EditPen'},{label:'创建试卷',path:'/papers/create',icon:'CirclePlus'},{label:'导入题目',path:'/questions/import',icon:'Upload'},{label:'题库管理',path:'/questions',icon:'Tickets'},{label:'系统设置',path:'/settings',icon:'Setting'}]
const dateText=computed(()=>new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date())),formatTime=value=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'-'
const load=async()=>{loading.value=true;error.value='';try{[stats.value,files.value,questions.value,papers.value]=await Promise.all([dashboardApi.stats(),dashboardApi.files(),dashboardApi.questions(),dashboardApi.papers()]);const[typeData,difficultyData,parseData]=await Promise.all([dashboardApi.typeChart(),dashboardApi.difficultyChart(),dashboardApi.parseChart()]);await nextTick();charts.forEach(chart=>chart.dispose());const typeChart=echarts.init(typeEl.value),difficultyChart=echarts.init(difficultyEl.value),parseChart=echarts.init(parseEl.value);typeChart.setOption({tooltip:{trigger:'item'},legend:{orient:'vertical',right:10,top:'middle'},series:[{type:'pie',radius:['46%','68%'],center:['35%','50%'],itemStyle:{borderColor:'#fff',borderWidth:3},data:typeData}]});difficultyChart.setOption({tooltip:{trigger:'axis'},grid:{left:48,right:20,top:30,bottom:42},xAxis:{type:'category',data:difficultyData.map(item=>item.name),axisTick:{show:false}},yAxis:{type:'value',minInterval:1,splitLine:{lineStyle:{color:'#edf0f5'}}},series:[{type:'bar',barWidth:32,data:difficultyData.map(item=>item.value),itemStyle:{color:'#13c2c2',borderRadius:[5,5,0,0]}}]});parseChart.setOption({tooltip:{trigger:'item'},legend:{bottom:8},series:[{type:'pie',radius:['44%','67%'],center:['50%','44%'],itemStyle:{borderColor:'#fff',borderWidth:3},data:parseData}]});charts=[typeChart,difficultyChart,parseChart]}catch(exc){error.value=exc.message}finally{loading.value=false}}
const resize=()=>charts.forEach(chart=>chart.resize());onMounted(()=>{load();addEventListener('resize',resize)});onUnmounted(()=>{removeEventListener('resize',resize);charts.forEach(chart=>chart.dispose())})
</script>
<style scoped>.welcome{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.welcome h1{font-size:27px;margin:0 0 4px}.welcome p{margin:0;color:var(--text-secondary)}.date{padding:10px 14px;background:#fff;border:1px solid var(--border);border-radius:9px;display:flex;align-items:center;gap:8px}.date svg{width:18px}.quick-actions{margin-top:18px;padding:14px 18px;display:flex;align-items:center;gap:10px}.quick-actions>span{font-weight:650;margin-right:6px}.quick-actions svg{width:16px;margin-right:5px}.chart-grid.three{grid-template-columns:repeat(3,1fr)}@media(max-width:1500px){.chart-grid.three{grid-template-columns:1fr 1fr}.chart-grid.three>:last-child{grid-column:1/-1}}</style>
